import{_ as n,y as o,a as s,o as i,a2 as t,D as r}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Exchange Rates","description":"","frontmatter":{},"headers":[],"relativePath":"configure/exchange-rates-configurations.md","filePath":"configure/exchange-rates-configurations.md","lastUpdated":1789395222000}'),h={name:"configure/exchange-rates-configurations.md"};function c(g,e,l,d,u,p){const a=o("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="exchange-rates" tabindex="-1">Exchange Rates <a class="header-anchor" href="#exchange-rates" aria-label="Permalink to &quot;Exchange Rates&quot;">​</a></h1><p>Bagisto can fetch current exchange rates from an exchange rate service, so prices shown in your other currencies stay correct without entering rates by hand. You can update the rates on demand or on a schedule.</p><p>Go to <strong>Configure &gt;&gt; General &gt;&gt; Exchange Rates</strong>.</p><h2 id="connect-an-exchange-rate-service" tabindex="-1">Connect an exchange rate service <a class="header-anchor" href="#connect-an-exchange-rate-service" aria-label="Permalink to &quot;Connect an exchange rate service&quot;">​</a></h2><p>Two services are supported. Sign up with one of them and copy your API key:</p><ul><li><strong>Exchange Rates API</strong> (<a href="https://www.exchangerate-api.com" target="_blank" rel="noreferrer">exchangerate-api.com</a>) returns the rates for every currency in one request.</li><li><strong>Fixer API</strong> (<a href="https://fixer.io" target="_blank" rel="noreferrer">fixer.io</a>) is asked for one currency at a time.</li></ul><ol><li>In <strong>General Settings</strong>, choose the <strong>Default Service</strong>.</li><li>In the <strong>Exchange Rates API</strong> or <strong>Fixer API</strong> section, enter the <strong>API Key</strong> of that service.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',7)),r(a,{src:"/images/configure/exchange-rates-settings.png",alt:"Exchange Rates screen with the General Settings, Exchange Rates API and Fixer API sections"}),e[1]||(e[1]=t('<p>If the API key is left empty, the store uses the key set in the server&#39;s environment file, if there is one.</p><h2 id="update-the-rates-on-a-schedule" tabindex="-1">Update the rates on a schedule <a class="header-anchor" href="#update-the-rates-on-a-schedule" aria-label="Permalink to &quot;Update the rates on a schedule&quot;">​</a></h2><ol><li>In <strong>Scheduled Import</strong>, switch <strong>Enabled</strong> on.</li><li>Choose the <strong>Frequency</strong>: <strong>Daily</strong>, <strong>Weekly</strong> (every Monday) or <strong>Monthly</strong> (on the first day of the month).</li><li>Enter the <strong>Start Time (HH:MM)</strong> in 24-hour format, such as <code>03:00</code>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),r(a,{src:"/images/configure/exchange-rates-schedule.png",alt:"Scheduled Import section set to update the rates daily at 03:00"}),e[2]||(e[2]=t('<p>Scheduled updates run on the server&#39;s task scheduler. If the rates don&#39;t update at the set time, ask whoever manages your server to check that the scheduler is running.</p><h2 id="update-the-rates-now" tabindex="-1">Update the rates now <a class="header-anchor" href="#update-the-rates-now" aria-label="Permalink to &quot;Update the rates now&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</li><li>Click <strong>Update Exchange Rate</strong>.</li></ol><p>The rates are fetched from the default service straight away. You can also enter a rate by hand on the same page; see <a href="./../settings/exchange-rates.html">Exchange Rates</a>.</p>',4))])}const x=n(h,[["render",c]]);export{_ as __pageData,x as default};
